11: export function retrieveLoggedInUser () {
12:   return (req: Request, res: Response) => {
13:     let user
14:     let response: any
15:     const emptyUser = { id: undefined, email: undefined, lastLoginIp: undefined, profileImage: undefined }
16:     try {
17:       if (security.verify(req.cookies.token)) {
18:         user = security.authenticatedUsers.get(req.cookies.token)
19: 
20:         // Parse the fields parameter into an array, splitting by comma.
21:         // If not provided, both these variables will be undefined.
22:         const fieldsParam = req.query?.fields as string | undefined
23:         const requestedFields = fieldsParam ? fieldsParam.split(',').map(f => f.trim()) : []
24: 
25:         let baseUser: any = {}
26: 
27:         if (requestedFields.length > 0) {
28:           // When fields are specified, return only those fields
29:           for (const field of requestedFields) {
30:             if (user?.data[field as keyof typeof user.data] !== undefined) {
31:               baseUser[field] = user?.data[field as keyof typeof user.data]
32:             }
33:           }
34:         } else {
35:           // If no fields parameter, return standard fields (not password field)
36:           baseUser = {
37:             id: user?.data?.id,
38:             email: user?.data?.email,
39:             lastLoginIp: user?.data?.lastLoginIp,
40:             profileImage: user?.data?.profileImage
41:           }
42:         }
43: 
44:         response = { user: baseUser }
45:       } else {
46:         response = { user: emptyUser }
47:       }
48:     } catch (err) {
49:       response = { user: emptyUser }
50:     }
51:     // Solve passwordHashLeakChallenge when password field is included in response
52:     challengeUtils.solveIf(challenges.passwordHashLeakChallenge, () => response?.user?.password)
53: 
54:     if (req.query.callback === undefined) {
55:       res.json(response)
56:     } else {
57:       challengeUtils.solveIf(challenges.emailLeakChallenge, () => { return true })
58:       res.jsonp(response)
59:     }
60:   }
61: }

