38: export const verifyImageCaptcha = () => async (req: Request, res: Response, next: NextFunction) => {
39:   try {
40:     const user = security.authenticatedUsers.from(req)
41:     const UserId = user ? user.data ? user.data.id : undefined : undefined
42:     const captchas = await ImageCaptchaModel.findAll({
43:       limit: 1,
44:       where: {
45:         UserId,
46:         createdAt: {
47:           [Op.gt]: new Date(Date.now() - 300000)
48:         }
49:       },
50:       order: [['createdAt', 'DESC']]
51:     })
52:     if (!captchas[0] || req.body.answer === captchas[0].answer) {
53:       next()
54:     } else {
55:       res.status(401).send(res.__('Wrong answer to CAPTCHA. Please try again.'))
56:     }
57:   } catch (error) {
58:     res.status(401).send(res.__('Something went wrong while submitting CAPTCHA. Please try again.'))
59:   }
60: }

